      if (lookahead == 'A') ADVANCE(27);
      END_STATE();
    case 2:
      if (lookahead == 'U') ADVANCE(28);
      END_STATE();
    case 3:
      if (lookahead == '_') ADVANCE(29);
      END_STATE();
    case 4:
